PREPARE find_user(bigint) AS SELECT *
FROM users
WHERE id = $1;
EXECUTE find_user(1);
DEALLOCATE find_user;

SELECT DISTINCT ON (department_id) department_id, id, created_at
FROM users
ORDER BY department_id, created_at DESC, id DESC;

SELECT u.id, s.status
FROM users u
CROSS JOIN (
  VALUES ('pending'), ('paid')
) AS s(status);

SELECT * FROM users u WHERE EXISTS (
  SELECT 1 FROM orders o WHERE o.user_id = u.id
);

SELECT id, user_id, amount, SUM(amount) OVER (
  PARTITION BY user_id
) AS user_total
FROM orders;

SELECT id, ROW_NUMBER() OVER (
  PARTITION BY user_id
  ORDER BY created_at, id
) AS n
FROM orders;

SELECT id, RANK() OVER (
  ORDER BY amount DESC
), DENSE_RANK() OVER (
  ORDER BY amount DESC
)
FROM orders;

SELECT id, LAG(amount) OVER (
  PARTITION BY user_id
  ORDER BY created_at, id
)
FROM orders;

SELECT id, SUM(amount) OVER (
  ORDER BY created_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
) AS running_total
FROM orders;

MERGE INTO users u USING (
  VALUES ('pomo@example.com', 'Pomo')
) AS s(email, name) ON u.email = s.email WHEN MATCHED THEN UPDATE SET name = s.name WHEN NOT MATCHED THEN INSERT (email, name) VALUES (s.email, s.name);

CREATE TABLE notes (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  body text NOT NULL
);

CREATE TABLE reviews (
  id bigint PRIMARY KEY,
  user_id bigint REFERENCES users(id)
);

CREATE TABLE sessions (
  id bigint PRIMARY KEY,
  user_id bigint REFERENCES users(id) ON DELETE CASCADE
);

SELECT DATE_TRUNC('month', created_at), COUNT(*)
FROM users
GROUP BY DATE_TRUNC('month', created_at);

CREATE MATERIALIZED VIEW user_totals AS SELECT user_id, SUM(amount) AS total
FROM orders
GROUP BY user_id;

BEGIN;
SAVEPOINT before_change;
UPDATE users SET active = false
WHERE id = 1;
ROLLBACK TO SAVEPOINT before_change;
COMMIT;

BEGIN;
SELECT *
FROM orders
WHERE status = 'pending'
ORDER BY id FOR UPDATE SKIP LOCKED
LIMIT 1;
COMMIT;

BEGIN;
SET LOCAL lock_timeout = '3s';
SELECT *
FROM users
WHERE id = 1 FOR UPDATE;
COMMIT;

COPY (
  SELECT id, name FROM users
) TO '/tmp/users.csv' WITH (FORMAT csv, HEADER true);
